{
  "identity": {
    "name": "AMP Electric",
    "location": "2328 W. Hemingway Blvd., Nampa, Idaho",
    "claims": [
      {
        "statement": "AMP Electric is a locally owned and operated family business based in Nampa, Idaho, serving the Treasure Valley.",
        "label": "fact",
        "sourceUrl": "https://amp240v.com/",
        "quote": "At Amp Electric, we are a locally owned and operated family business proudly serving Nampa, Idaho, and the Treasure Valley."
      },
      {
        "statement": "The company's street address is 2328 W. Hemingway Blvd.",
        "label": "fact",
        "sourceUrl": "https://amp240v.com/",
        "quote": "Address : 2328 W. Hemingway Blvd."
      },
      {
        "statement": "AMP Electric states it has been operating in Nampa since 1996.",
        "label": "fact",
        "sourceUrl": "https://amp240v.com/",
        "quote": "Amp Electric - Your Trusted Nampa Electricians Since 1996"
      },
      {
        "statement": "[redacted] is the Owner and [redacted] is the General Manager of AMP Electric.",
        "label": "fact",
        "sourceUrl": "https://amp240v.com/",
        "quote": "[redacted] General Manager [redacted] Owner"
      }
    ]
  },
  "industry": {
    "industry": "Electrical Contracting (Home and Commercial Services)",
    "activities": [
      "Residential, commercial, and industrial electrical repairs and troubleshooting",
      "Electrical panel upgrades, service changes, and electrical inspections",
      "Lighting, ceiling fan, bath fan, and smart home automation (Lutron Radio RA3) installation",
      "EV charging station installation",
      "Backup generator installation and maintenance",
      "Whole-house surge protection, circuit wiring, low-voltage cabling, and hardwired smoke/CO detector installation"
    ],
    "claims": [
      {
        "statement": "AMP Electric provides electrical services to residential, commercial, and industrial customers.",
        "label": "fact",
        "sourceUrl": "https://amp240v.com/",
        "quote": "At Amp Electric, we offer a full range of electrical services for residential, commercial, and industrial clients."
      },
      {
        "statement": "Principal services include panel upgrades, rewiring, lighting installation, troubleshooting, electrical repairs, and EV charger installations.",
        "label": "fact",
        "sourceUrl": "https://amp240v.com/",
        "quote": "Our services include panel upgrades, rewiring, lighting installation, troubleshooting, electrical repairs, EV charger installations, and more."
      },
      {
        "statement": "The company installs and maintains backup generators.",
        "label": "fact",
        "sourceUrl": "https://amp240v.com/",
        "quote": "Ensure uninterrupted power during outages with our reliable backup generator installation and maintenance services, tailored to meet your specific needs."
      },
      {
        "statement": "The company installs and configures Lutron Radio RA3 smart-home controls, switches, dimmers, and plugs.",
        "label": "fact",
        "sourceUrl": "https://amp240v.com/electrical-services",
        "quote": "Smart-home switches, dimmers and plugs, from brands listed below. Lutron Radio RA3 controls, installation and configuration."
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://amp240v.com/",
    "claims": [
      {
        "statement": "Standard business hours are Monday through Friday from 7:30 am to 4:30 pm.",
        "label": "fact",
        "sourceUrl": "https://amp240v.com/",
        "quote": "Hours of Operation: Monday - Friday | 7:30 am - 4:30 pm"
      },
      {
        "statement": "AMP Electric advertises 24/7 emergency electrical services as well as same-day or next-day appointments.",
        "label": "fact",
        "sourceUrl": "https://amp240v.com/",
        "quote": "We also provide 24/7 emergency services for critical electrical problems."
      },
      {
        "statement": "AMP Electric charges $89 for a 30-minute onsite estimate in the Treasure Valley, credited toward the final bill if hired.",
        "label": "fact",
        "sourceUrl": "https://amp240v.com/",
        "quote": "For an onsite estimate in the Treasure Valley, we charge a modest $89 for a 30-minute consultation."
      },
      {
        "statement": "The company serves Boise, Meridian, Eagle, Star, Kuna, Nampa, Caldwell, Middleton, and areas from Mountain Home to Fruitland across Ada and Canyon counties.",
        "label": "fact",
        "sourceUrl": "https://amp240v.com/",
        "quote": "Amp Electric proudly serves the entire Treasure Valley, including Boise, Meridian, Eagle, Star, Kuna, Nampa, Caldwell, and Middleton."
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "AMP Electric states on its website that it is licensed, insured, and certified to perform electrical work.",
        "label": "fact",
        "sourceUrl": "https://amp240v.com/",
        "quote": "Yes, Amp Electric is fully licensed, insured, and certified to perform electrical work."
      },
      {
        "statement": "The company states that it provides proof of credentials upon request rather than listing license numbers on the website.",
        "label": "fact",
        "sourceUrl": "https://amp240v.com/",
        "quote": "We’re happy to provide proof of our credentials upon request."
      }
    ],
    "limitations": "Specific Idaho electrical contractor license numbers and state business registration identifiers are not published on the website and cannot be independently verified solely from the company's public pages."
  },
  "existingSoftware": [
    {
      "product": "Synchrony",
      "purpose": "Customer project financing",
      "evidence": {
        "statement": "AMP Electric partners with Synchrony to offer customer financing for electrical projects.",
        "label": "fact",
        "sourceUrl": "https://amp240v.com/electrician-with-financing",
        "quote": "Amp Electric, in partnership with Synchrony, offers convenient financing options to help you start your project today and pay over time."
      }
    },
    {
      "product": "Online booking and appointment notification system",
      "purpose": "Online appointment scheduling and SMS/email appointment notifications",
      "evidence": {
        "statement": "The website states that it provides an online booking system for scheduling consultations, repairs, and installations.",
        "label": "fact",
        "sourceUrl": "https://amp240v.com/",
        "quote": "Our online booking system makes it easy to schedule an appointment for an electrical assessment, repair, install, or project consultation."
      }
    },
    {
      "product": "LeadConnector / GoHighLevel CRM and website builder",
      "purpose": "Website hosting, web form capture, and SMS/email lead management",
      "evidence": {
        "statement": "The website loads scripts and references from stcdn.leadconnectorhq.com, backend.leadconnectorhq.com, services.leadconnectorhq.com, payment-embed.leadconnectorhq.com, and cdn.msgsndr.com, which likely correspond to the LeadConnector / GoHighLevel platform.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "Authorize.Net",
      "purpose": "Payment processing",
      "evidence": {
        "statement": "The website references js.authorize.net and jstest.authorize.net, which likely indicate Authorize.Net payment integration.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The financing page contains unedited placeholder copy ('Small Call to Action', 'Headline', and 'Lorem ipsum') in the application instructions.",
      "label": "fact",
      "sourceUrl": "https://amp240v.com/electrician-with-financing",
      "quote": "Fill out Application: Lorem ipsum dolor sit amet consectetur. Aliquam odio enim pharetra et. Diam varius magna lobortis consequat elit."
    },
    {
      "statement": "The services page instructs visitors to call [redacted] in the body text while displaying [redacted] in the header and footer.",
      "label": "fact",
      "sourceUrl": "https://amp240v.com/electrical-services",
      "quote": "so if you don’t see what you’re looking for, just give us a call at [redacted]."
    },
    {
      "statement": "The services page refers twice to smart-home device brands 'listed below', but no brand list is present on the page.",
      "label": "fact",
      "sourceUrl": "https://amp240v.com/electrical-services",
      "quote": "Smart-home switches, dimmers and plugs, from brands listed below."
    },
    {
      "statement": "The contact form collects consent for text and email appointment messages.",
      "label": "fact",
      "sourceUrl": "https://amp240v.com/contact-us",
      "quote": "By providing my phone number & email address, I agree to receive text/email messages about my appointment."
    },
    {
      "statement": "The presence of unfinished template text, missing reference lists, and two different phone numbers suggests the website and its underlying CRM/lead workflows may have been only partially configured.",
      "label": "inference",
      "sourceUrl": "https://amp240v.com/electrician-with-financing",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "Website pages contain unfinished template text ('Lorem ipsum'), omitted smart-home brand lists, and two different phone numbers ([redacted] and [redacted]).",
      "label": "fact",
      "basis": "Directly observed on https://amp240v.com/electrician-with-financing and https://amp240v.com/electrical-services."
    },
    {
      "problem": "Inbound calls or leads across two published phone numbers, web forms, and after-hours 24/7 emergency inquiries outside the 7:30 am – 4:30 pm weekday office window may not be consistently tracked, answered, or synced into field-service dispatch software.",
      "label": "hypothesis",
      "basis": "Plausible operational risk given the two phone numbers on the site, the gap between 7:30 am – 4:30 pm office hours and 24/7 emergency availability, and signs of an incompletely finished website setup, though actual call-handling performance cannot be verified publicly."
    },
    {
      "problem": "Leadership may lack a single automated weekly view combining booked revenue, close rates, average ticket, and lead-source ROI across their CRM, field-service system, and accounting software.",
      "label": "hypothesis",
      "basis": "Common challenge for owner-led electrical contractors operating multiple systems, though internal reporting practices are not visible on the website."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Built-in CRM and automation workflows on the existing website platform (referencing leadconnectorhq.com / msgsndr.com)",
      "addresses": "Instant SMS/email lead response, missed-call text-back, online booking confirmation, and call tracking across phone numbers",
      "alreadyOwned": true
    },
    {
      "solution": "Native reporting in existing field-service management and accounting software",
      "addresses": "Job costing, invoice tracking, and basic revenue reporting",
      "alreadyOwned": false
    }
  ],
  "forgexSolutions": [
    {
      "name": "Revenue Leak Check",
      "kind": "catalog",
      "description": "One-week audit ($500 fixed price, credited toward any fix ordered within 30 days) to measure how many calls, web leads, and $89 consultation requests across both published phone numbers and after-hours windows slip through or fail to convert.",
      "problem": "Potential lead and call leakage across multiple phone numbers ([redacted] and [redacted]), unfinished website conversion flows, and after-hours emergency inquiries.",
      "whyNotExistingSoftware": "While the company already hosts its site on a platform that supports lead tracking (leadconnectorhq.com), the unfinished pages suggest the platform's tracking and automation workflows may not be fully audited or connected to actual job conversion outcomes."
    },
    {
      "name": "Lead-to-job pipeline",
      "kind": "catalog",
      "description": "Automated pipeline ($1,800 setup plus $149/month) ensuring every lead from web forms, online booking, and both phone lines gets an instant reply and lands in their field-service or dispatch system within two minutes.",
      "problem": "Potential manual re-entry or delayed follow-up between the website CRM and field-service scheduling software.",
      "whyNotExistingSoftware": "Web-marketing CRMs typically do not sync natively out-of-the-box with specialized electrical field-service dispatch and estimating software without custom webhook/API bridging."
    },
    {
      "name": "Owner's Monday numbers",
      "kind": "catalog",
      "description": "Automated weekly one-page summary ($1,200 setup plus $99/month) delivering booked revenue, close rate, average ticket, cost per booked job by lead source, and accounts receivable.",
      "problem": "Potential fragmentation of lead data, job revenue, and accounting receivables across separate tools.",
      "whyNotExistingSoftware": "Requires cross-system data aggregation across ad accounts, the website CRM, field-service dispatch software, and accounting software."
    }
  ],
  "feasibility": {
    "rating": "medium",
    "explanation": "The website already runs on a modern web/CRM stack (referencing leadconnectorhq.com and services.leadconnectorhq.com) that supports webhooks and API integrations, making a Revenue Leak Check and Lead-to-job pipeline technically straightforward once the back-office field-service and accounting systems are identified."
  },
  "aiDelivery": {
    "rating": "partly",
    "explanation": "Deterministic workflow automation and API integrations should handle lead routing, instant SMS/email replies, and weekly KPI aggregation; AI agents can assist in classifying unstructured inquiry descriptions (e.g., separating urgent 24/7 electrical emergencies from routine $89 estimate requests) and summarizing call transcripts."
  },
  "humanReview": [
    "Owner or General Manager approval of all customer-facing SMS and email response templates prior to activation.",
    "Dispatcher review of any emergency or safety-critical electrical inquiries (such as panel hazards or power outages) rather than relying on automated triage alone.",
    "Verification of mapping rules before writing customer or job records into field-service or accounting software."
  ],
  "risks": [
    {
      "type": "compliance",
      "description": "Automated SMS and voice follow-ups must strictly adhere to TCPA opt-in and opt-out rules, even though the contact form already includes an SMS/email consent checkbox."
    },
    {
      "type": "operational",
      "description": "Misclassifying a 24/7 emergency electrical call or live-wire hazard as a routine consultation could delay urgent response and create safety or liability issues."
    },
    {
      "type": "security",
      "description": "Customer contact details, service addresses, and payment/financing references must be handled with least-privilege API credentials and never exposed in unencrypted logs."
    }
  ],
  "commercial": {
    "supportable": true,
    "value": "Illustrative consultation fee recovery of $178 to $445 per month ($2,136 to $5,340 per year) in onsite consultation fees alone (2 to 5 recovered consultations per month × $89 published consultation fee), before counting downstream installation or repair revenue if hired.",
    "implementationCost": "$500 fixed price for the initial Revenue Leak Check (credited in full toward any fix ordered within 30 days); if needed afterward, $1,800 setup plus $149/month for the Lead-to-job pipeline or $1,200 setup plus $99/month for Owner's Monday numbers.",
    "assumptions": [
      "Uses the site's only published price: $89 for a 30-minute onsite consultation in the Treasure Valley (which is credited toward the final bill if the customer hires AMP Electric).",
      "Assumes 2 to 5 additional inquiries per month are captured and converted into paid $89 onsite consultations through faster response and unified call/form tracking.",
      "Excludes project installation or repair ticket values (such as panel upgrades, EV chargers, or backup generators) because project prices are not published on the website."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner",
      "General Manager"
    ],
    "people": [
      {
        "name": "[redacted]",
        "role": "Owner",
        "sourceUrl": "https://amp240v.com/",
        "quote": "[redacted] Owner"
      },
      {
        "name": "[redacted]",
        "role": "General Manager",
        "sourceUrl": "https://amp240v.com/",
        "quote": "[redacted] General Manager"
      }
    ],
    "channels": [
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://amp240v.com/"
      }
    ]
  },
  "discovery": {
    "questions": [
      "We noticed your site runs on a CRM platform with online booking, but a few pages still have placeholder text and two different phone numbers ([redacted] and [redacted])—are calls and form submissions from both lines routing cleanly into your dispatch schedule right now?",
      "What field-service management and accounting software does your team use once a customer books an $89 consultation or requests an estimate?",
      "How are after-hours and weekend 24/7 emergency electrical calls currently handled and logged when the office is closed after 4:30 pm?",
      "Approximately how many electricians and office staff are on the AMP Electric team today, and are you running paid search or local ads to drive leads?"
    ],
    "outreachSubject": "Quick question on AMP Electric's website & lead routing",
    "outreachBody": "Hi [redacted],\n\nI was looking through AMP Electric's website (https://amp240v.com/) and noticed a couple of small items on your live pages that might be affecting incoming inquiries:\n\n1. Your Financing page (/electrician-with-financing) still has 'Lorem ipsum' placeholder text under the application steps.\n2. Your Services page (/electrical-services) asks customers to call [redacted] in the text while the rest of the site lists [redacted], and references a list of smart-home brands below that isn't showing up.\n\nBecause your site already uses a modern CRM setup for online booking and text/email notifications, you may already have most of the tools you need in place. However, when a site setup is left partway finished by an agency or builder, we often find that missed-call follow-ups, after-hours emergency inquiries, or handoffs into field-service software have silent gaps too.\n\nAt ForgeX, we run a fixed-price Revenue Leak Check ($500, credited in full if you ask us to build any fix within 30 days) where we audit one week of calls, web forms, and $89 consultation requests to see if anything is slipping through—or confirm that your current system is already catching everything.\n\nIf it would be helpful to compare notes on how your current setup is working, just reply to this email or let me know a good time for a brief call.\n\nBest regards,\n\n[Founder Name]\n[Founder Title], ForgeX\n[ForgeX Phone Number]\n[ForgeX Physical Postal Address]\n\nIf you prefer not to receive future emails from us, simply reply with \"unsubscribe\" or use [Opt-Out Link/Instructions] and we will remove you immediately."
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://amp240v.com/",
        "usedFor": "Business identity, Nampa address, operating history since 1996, leadership names ([redacted], Owner; [redacted], General Manager), services, $89 consultation fee, service area, office hours, 24/7 emergency availability, and online booking claim."
      },
      {
        "url": "https://amp240v.com/electrical-services",
        "usedFor": "Detailed list of electrical services, Lutron Radio RA3 installation, missing smart-home brand list reference, and secondary phone number ([redacted])."
      },
      {
        "url": "https://amp240v.com/electrician-with-financing",
        "usedFor": "Synchrony financing partnership and observation of unedited 'Lorem ipsum' template placeholder copy."
      },
      {
        "url": "https://amp240v.com/contact-us",
        "usedFor": "Contact form fields, SMS/email appointment consent language, and technical script/host references."
      },
      {
        "url": "https://amp240v.com/amp-electric-home",
        "usedFor": "Verification that the /amp-electric-home link duplicates the main homepage content."
      }
    ],
    "limitations": [
      "Exact employee headcount (whether within ForgeX's 10-to-75 staff target range) is not stated on the website.",
      "Whether AMP Electric currently pays for leads or digital advertising cannot be confirmed from the website alone.",
      "The website obfuscates the email address behind Cloudflare email protection ([email protected]), leaving phone and web form as the only directly readable contact channels.",
      "Specific field-service management and accounting software used internally behind the website cannot be observed from public pages.",
      "State electrical contractor license numbers are not displayed on the website."
    ]
  },
  "qualification": {
    "category": "pursue later",
    "rationale": "AMP Electric is an established, owner-led residential and commercial electrical contractor in Nampa, Idaho (operating since 1996, led by Owner [redacted] and General Manager [redacted]). While public pages show factual website maintenance oversights—such as 'Lorem ipsum' placeholder text on the financing page and two different phone numbers on the services page—the company already uses a CRM/booking platform (referencing leadconnectorhq.com) with online scheduling and SMS/email opt-in. Because internal lead-handling problems, staff count (10–75), and paid lead spend are unconfirmed hypotheses rather than verified facts, 'pursue later' is the appropriate qualification."
  }
}
